#!/usr/bin/env python3
"""Generate frontend TypeScript contracts from backend API definitions."""

from __future__ import annotations

import argparse
import difflib
import re
import sys
from pathlib import Path
from types import SimpleNamespace
from typing import Any


REPO_ROOT = Path(__file__).resolve().parents[1]
CONTRACTS_DIR = REPO_ROOT / "frontend" / "src" / "contracts"
BACKEND_API_GENERATED_PATH = CONTRACTS_DIR / "backendApi.generated.ts"
STREAM_EVENTS_PATH = CONTRACTS_DIR / "streamEvents.ts"


HEADER = """// Generated by scripts/generate_frontend_api_contract.py.
// Do not edit manually. Run the generator after backend contract changes.

"""


def _ensure_backend_import_path() -> None:
    for path in (REPO_ROOT / "backend", REPO_ROOT):
        value = str(path)
        if value not in sys.path:
            sys.path.insert(0, value)


def _load_openapi_schema() -> dict[str, Any]:
    _ensure_backend_import_path()

    from app.application import create_app

    settings = SimpleNamespace(
        app_name="EvoDiagram API Contract",
        app_version="contract",
        debug=False,
        cors_origins_list=["http://localhost:5175"],
    )
    app = create_app(settings=settings, configure_logs=False, load_env=False)
    return app.openapi()


def _load_stream_event_contract() -> dict[str, tuple[str, ...]]:
    _ensure_backend_import_path()

    from app.services.workflow_runtime.event_payloads import (
        REFINE_COMPLETE_STATUSES,
        STREAM_ERROR_STAGE_VALUES,
        STREAM_EVENT_TYPES,
        STREAM_STAGE_VALUES,
    )

    return {
        "STREAM_STAGES": tuple(STREAM_STAGE_VALUES),
        "STREAM_ERROR_STAGES": tuple(STREAM_ERROR_STAGE_VALUES),
        "STREAM_REFINE_STATUSES": tuple(REFINE_COMPLETE_STATUSES),
        "STREAM_EVENT_TYPES": tuple(STREAM_EVENT_TYPES),
    }


def _quote_string(value: str) -> str:
    escaped = value.replace("\\", "\\\\").replace("'", "\\'")
    return f"'{escaped}'"


def _literal(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    return _quote_string(str(value))


def _ts_name(schema_name: str) -> str:
    parts = [part for part in re.split(r"[^A-Za-z0-9]+", schema_name) if part]
    if not parts:
        raise ValueError(f"Cannot build TypeScript name for schema {schema_name!r}")
    return "Backend" + "".join(part[:1].upper() + part[1:] for part in parts)


def _ref_name(ref: str) -> str:
    return _ts_name(ref.rsplit("/", 1)[-1])


def _property_name(name: str) -> str:
    if re.match(r"^[A-Za-z_$][A-Za-z0-9_$]*$", name):
        return name
    return _quote_string(name)


def _unique(types: list[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in types:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result


def _schema_type(schema: dict[str, Any]) -> str:
    if "$ref" in schema:
        return _ref_name(str(schema["$ref"]))

    if "const" in schema:
        return _literal(schema["const"])

    if "enum" in schema:
        values = [_literal(value) for value in schema["enum"]]
        return " | ".join(_unique(values)) or "unknown"

    for union_key in ("anyOf", "oneOf"):
        variants = schema.get(union_key)
        if isinstance(variants, list):
            values = [_schema_type(variant) for variant in variants]
            return " | ".join(_unique(values)) or "unknown"

    all_of = schema.get("allOf")
    if isinstance(all_of, list):
        values = [_schema_type(variant) for variant in all_of]
        unique_values = _unique(values)
        if len(unique_values) > 1:
            return " & ".join(unique_values)
        return unique_values[0] if unique_values else "unknown"

    schema_type = schema.get("type")
    if isinstance(schema_type, list):
        values = [_schema_type({**schema, "type": item}) for item in schema_type]
        return " | ".join(_unique(values)) or "unknown"

    if schema_type == "string":
        return "string"
    if schema_type in {"integer", "number"}:
        return "number"
    if schema_type == "boolean":
        return "boolean"
    if schema_type == "null":
        return "null"
    if schema_type == "array":
        items = schema.get("items")
        item_type = _schema_type(items) if isinstance(items, dict) else "unknown"
        return f"Array<{item_type}>"
    if schema_type == "object":
        properties = schema.get("properties")
        if isinstance(properties, dict) and properties:
            return _inline_object_type(schema)

        additional = schema.get("additionalProperties")
        if isinstance(additional, dict):
            return f"Record<string, {_schema_type(additional)}>"
        if additional is False:
            return "Record<string, never>"
        return "Record<string, unknown>"

    additional = schema.get("additionalProperties")
    if isinstance(additional, dict):
        return f"Record<string, {_schema_type(additional)}>"
    if additional is True:
        return "Record<string, unknown>"

    return "unknown"


def _inline_object_type(schema: dict[str, Any]) -> str:
    properties = schema.get("properties", {})
    required = set(schema.get("required", []))
    fields: list[str] = ["{"]
    for name, property_schema in properties.items():
        optional = "" if name in required else "?"
        fields.append(
            f"  {_property_name(name)}{optional}: {_schema_type(property_schema)};"
        )
    fields.append("}")
    return "\n".join(fields)


def _render_component(name: str, schema: dict[str, Any]) -> str:
    ts_name = _ts_name(name)
    properties = schema.get("properties")
    if schema.get("type") == "object" and isinstance(properties, dict) and properties:
        required = set(schema.get("required", []))
        lines = [f"export interface {ts_name} {{"]
        for property_name, property_schema in properties.items():
            optional = "" if property_name in required else "?"
            lines.append(
                f"  {_property_name(property_name)}{optional}: {_schema_type(property_schema)};"
            )
        lines.append("}")
        return "\n".join(lines)

    return f"export type {ts_name} = {_schema_type(schema)};"


def render_typescript(openapi_schema: dict[str, Any]) -> str:
    schemas = openapi_schema.get("components", {}).get("schemas", {})
    if not isinstance(schemas, dict) or not schemas:
        raise ValueError("OpenAPI schema has no components.schemas section")

    components = [
        _render_component(name, schemas[name])
        for name in sorted(schemas)
    ]
    return HEADER + "\n\n".join(components) + "\n"


def _render_const_string_array(name: str, values: tuple[str, ...]) -> str:
    rendered_values = ", ".join(_quote_string(value) for value in values)
    return f"export const {name} = [{rendered_values}] as const;"


def render_stream_events_typescript(contract: dict[str, tuple[str, ...]]) -> str:
    lines = [
        HEADER.rstrip(),
        "",
        _render_const_string_array("STREAM_STAGES", contract["STREAM_STAGES"]),
        "",
        _render_const_string_array(
            "STREAM_ERROR_STAGES",
            contract["STREAM_ERROR_STAGES"],
        ),
        "",
        _render_const_string_array(
            "STREAM_REFINE_STATUSES",
            contract["STREAM_REFINE_STATUSES"],
        ),
        "",
        _render_const_string_array("STREAM_EVENT_TYPES", contract["STREAM_EVENT_TYPES"]),
        "",
        "export type StreamStage = typeof STREAM_STAGES[number];",
        "export type StreamErrorStage = typeof STREAM_ERROR_STAGES[number];",
        "export type StreamRefineStatus = typeof STREAM_REFINE_STATUSES[number];",
        "export type StreamEventType = typeof STREAM_EVENT_TYPES[number];",
        "",
    ]
    return "\n".join(lines)


def render_contract_outputs() -> dict[Path, str]:
    return {
        BACKEND_API_GENERATED_PATH: render_typescript(_load_openapi_schema()),
        STREAM_EVENTS_PATH: render_stream_events_typescript(_load_stream_event_contract()),
    }


def _check_output(path: Path, expected: str) -> int:
    current = path.read_text(encoding="utf-8") if path.exists() else ""
    if current == expected:
        return 0

    diff = difflib.unified_diff(
        current.splitlines(),
        expected.splitlines(),
        fromfile=str(path),
        tofile=f"{path} (generated)",
        lineterm="",
    )
    sys.stderr.write("\n".join(diff))
    sys.stderr.write("\n")
    return 1


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="Fail if generated output is stale")
    mode.add_argument("--write", action="store_true", help="Write generated contract files")
    args = parser.parse_args(argv)

    outputs = render_contract_outputs()
    if args.check:
        return max(_check_output(path, expected) for path, expected in outputs.items())

    for path, rendered in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(rendered, encoding="utf-8")
        print(f"Wrote {path.relative_to(REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
